<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {X,ArrowRight,Heading2,List,Braces,Quote,Eye,Columns2,FolderPlus,Sprout,Check,FileText} from 'lucide-vue-next';
const props=defineProps(['initial','editId','folders','busy','demo']);const emit=defineEmits(['close','save','folders']);
const data=ref({...props.initial}),textarea=ref(null),view=ref('split'),draftAvailable=ref(false),draftSaved=ref(false);
const key='study-garden-draft-'+(props.editId||'new');let timer;
const keywordCount=computed(()=>[...data.value.content.matchAll(/\[\[([^\[\]\n]+)\]\]/g)].length);
const lines=computed(()=>data.value.content.split('\n'));
const dirty=computed(()=>JSON.stringify(data.value)!==JSON.stringify(props.initial));
function close(){if(!dirty.value||confirm('笔记尚未保存到数据库，确定关闭？本地草稿会保留。'))emit('close');}
function persist(){if(props.demo)return;try{localStorage.setItem(key,JSON.stringify(data.value));draftSaved.value=true;}catch{draftSaved.value=false;}}
function restore(){try{const d=JSON.parse(localStorage.getItem(key));if(d&&typeof d.title==='string'&&typeof d.content==='string'){data.value={...data.value,...d};}}catch{}draftAvailable.value=false;}
function discard(){localStorage.removeItem(key);draftAvailable.value=false;}
watch(data,()=>{draftSaved.value=false;clearTimeout(timer);timer=setTimeout(persist,600);},{deep:true});
watch(()=>props.folders,folders=>{if(!data.value.category&&folders.length)data.value.category=folders[0].path;});
function submit(){if(!data.value.category)return;emit('save',{...data.value});}
function insert(kind){const el=textarea.value;if(!el)return;const start=el.selectionStart,end=el.selectionEnd,value=data.value.content,selection=value.slice(start,end);const text=kind==='keyword'?`[[${selection||'关键词'}]]`:kind==='heading'?`\n# ${selection||'新的主题'}\n`:kind==='list'?`\n- ${selection||'记录一个知识点'}`:`\n> ${selection||'写下自己的理解'}`;data.value.content=value.slice(0,start)+text+value.slice(end);nextTick(()=>{el.focus();el.setSelectionRange(start+(kind==='keyword'?2:0),start+text.length-(kind==='keyword'?2:0));});}
function keys(e){if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();if(!props.busy&&data.value.title.trim()&&data.value.content.trim()&&data.value.category)submit();}if(e.key==='Escape')close();}
onMounted(()=>{if(!props.demo)try{draftAvailable.value=!!localStorage.getItem(key);}catch{}document.addEventListener('keydown',keys);});
onUnmounted(()=>{clearTimeout(timer);document.removeEventListener('keydown',keys);});
defineExpose({clearDraft:()=>{if(!props.demo)localStorage.removeItem(key)},selectFolder:change=>{if(change.method==='POST')data.value.category=change.path;else if(change.path&&change.oldPath&&(data.value.category===change.oldPath||data.value.category.startsWith(change.oldPath+'/')))data.value.category=change.path+data.value.category.slice(change.oldPath.length);else if(change.method==='DELETE'&&data.value.category===change.oldPath)data.value.category='';}});
</script>
<template><div class="modal-backdrop writing-backdrop" @click.self="close"><form class="writing-studio" @submit.prevent="submit"><header class="studio-header"><div class="studio-brand"><span><img src="/shizhi-logo.svg" alt="" width="37" height="37"/></span><div><b>{{editId?'打磨一个想法':'捕捉今天的新知'}}</b><small>YOUR LITTLE WRITING STUDIO</small></div></div><div class="studio-header-actions"><span class="draft-status"><Check v-if="draftSaved" :size="13"/>{{draftSaved?'草稿已保存在本机':'专注当下，慢慢写'}}</span><button type="button" class="icon-button" aria-label="关闭编辑器" @click="close"><X :size="21"/></button></div></header><div class="studio-scroll"><div v-if="draftAvailable" class="draft-banner">发现尚未提交的本地草稿<button type="button" @click="restore">恢复草稿</button><button type="button" @click="discard">忽略</button></div><div class="studio-title"><div class="eyebrow">{{editId?'REVISIT & REFINE':'A NEW PAGE, A NEW POSSIBILITY'}}</div><input class="title-input" v-model="data.title" required maxlength="160" aria-label="笔记标题" placeholder="今天，你想留下什么？"/><div class="studio-meta"><label><span>学习日期</span><input type="date" required v-model="data.day"/></label><label class="folder-select"><span>收纳到</span><select v-model="data.category" required><option value="" disabled>请选择文件夹</option><option v-for="f in folders" :value="f.path">{{f.path}}</option></select></label><button type="button" class="text-button" @click="emit('folders')"><FolderPlus :size="15"/>新建文件夹</button></div></div><div class="studio-toolbar"><div><button type="button" title="插入小标题" aria-label="插入小标题" @click="insert('heading')"><Heading2 :size="18"/></button><button type="button" title="插入列表" aria-label="插入列表" @click="insert('list')"><List :size="18"/></button><button type="button" title="标记填空关键词" aria-label="标记填空关键词" @click="insert('keyword')"><Braces :size="18"/></button><button type="button" title="插入自己的理解" aria-label="插入自己的理解" @click="insert('quote')"><Quote :size="17"/></button><span class="toolbar-hint">选中文字，标记为填空</span></div><div class="view-switch"><button type="button" :class="{chosen:view==='write'}" @click="view='write'"><FileText :size="14"/>写作</button><button type="button" :class="{chosen:view==='split'}" @click="view='split'"><Columns2 :size="14"/>分屏</button><button type="button" :class="{chosen:view==='preview'}" @click="view='preview'"><Eye :size="14"/>预览</button></div></div><div class="studio-pages" :class="view"><div v-show="view!=='preview'" class="write-pane"><div class="pane-label">你的思考</div><textarea ref="textarea" v-model="data.content" :required="view!=='preview'" maxlength="50000" aria-label="学习内容" placeholder="# 一个新的主题&#10;&#10;从今天最有启发的一个想法开始……&#10;&#10;用 [[关键词]] 标记你想记住的内容。"></textarea></div><div v-show="view!=='write'" class="preview-pane"><div class="pane-label">阅读预览 <span>关键词会生成填空练习</span></div><div v-if="!data.content" class="preview-placeholder"><Sprout :size="30"/><p>你的想法将在这里生长。</p></div><template v-for="(line,i) in lines" :key="i"><h3 v-if="/^#+\s/.test(line)">{{line.replace(/^#+\s*/,'')}}</h3><p v-else :class="{quoted:line.startsWith('>'),listed:/^[-*]\s/.test(line)}"><template v-for="(piece,j) in line.replace(/^[>*-]\s/,'').split(/\[\[([^\[\]\n]+)\]\]/g)"><mark v-if="j%2">{{piece}}</mark><span v-else>{{piece}}</span></template></p></template></div></div></div><div class="studio-footer"><div><span>{{data.content.length.toLocaleString()}} 字</span><span>{{keywordCount}} 个填空关键词</span><label class="checkbox"><input type="checkbox" v-model="data.published"/>发布到知识博客</label></div><button class="primary" :disabled="busy||!data.category||!data.title.trim()||!data.content.trim()">{{busy?'正在保存…':'保存这份收获'}}<ArrowRight :size="17"/></button></div></form></div></template>

